/**
 * Processes a where clause,
 * both using and augmenting the environment
 * "interior" passed in as a parameter.
 *
 * @param wheres
 * @param interior
 * @return
 */
private static EvalType processWhereClauses(WhereClause wheres, Environment interior) {

    if (wheres != null) {
        // A nat or int where-clause variable stands for every size, as a
        // static parameter does in a symbolic instantiation: comprises
        // { N[\n\] } where [\nat n\] lists N at every n.  A type where-clause
        // variable stands for every type, as a type static parameter does
        // (SingleFcn.createSymbolicInstantiation): comprises { List[\E\] }
        // where [\E\] lists List at every E.
        List<WhereBinding> typeBindings = new ArrayList<WhereBinding>();
        for (WhereBinding b : wheres.getBindings()) {
            if (b.getKind() instanceof KindNat || b.getKind() instanceof KindInt) {
                String string_name = NodeUtil.nameString(b.getName());
                if (interior.getLeafTypeNull(string_name) == null)
                    interior.putType(string_name, new SymbolicNat(string_name));
            } else if (b.getKind() instanceof KindType) {
                String string_name = NodeUtil.nameString(b.getName());
                if (interior.getLeafTypeNull(string_name) == null) {
                    interior.putType(string_name, new SymbolicInstantiatedType(string_name, interior, b));
                    typeBindings.add(b);
                }
            }
        }
        for (WhereBinding b : typeBindings) {
            SymbolicInstantiatedType st =
                (SymbolicInstantiatedType) interior.getLeafType(NodeUtil.nameString(b.getName()));
            st.setExtendsAndExcludes(new EvalType(interior).getFTypeListFromList(b.getSupers()), null);
        }
        for (WhereConstraint w : wheres.getConstraints()) {
            if (w instanceof WhereExtends) {
                WhereExtends we = (WhereExtends) w;
                Id name = we.getName();
                String string_name = NodeUtil.nameString(name);
                // List<Type> types = we.getSupers();
                FType ft = interior.getLeafTypeNull(string_name); // leaf
                if (ft == null) {
                    ft = new SymbolicWhereType(string_name, interior, we);
                    interior.putType(string_name, ft);
                }
            } else {
                bug(w, errorMsg("Where clause ", w));
            }
        }
    }

    EvalType et = new EvalType(interior);

    if (wheres != null) {
        for (WhereConstraint w : wheres.getConstraints()) {
            if (w instanceof WhereExtends) {
                WhereExtends we = (WhereExtends) w;
                Id name = we.getName();
                String string_name = NodeUtil.nameString(name);
                List<BaseType> types = we.getSupers();
                FType ft = interior.getLeafTypeNull(string_name); // leaf
                for (Type t : types) {
                    FType st = et.evalType(t); // t.visit(et);
                    if (ft instanceof SymbolicType) {
                        // Treat as "extends".
                        ((SymbolicType) ft).addExtend(st);
                    } else if (st instanceof SymbolicWhereType) {
                        // Record subtype ft of st.
                        SymbolicWhereType swt = (SymbolicWhereType) st;
                        swt.addSubtype(ft);
                    } else {
                        ft.mustExtend(st, w);
                        // Check that constraint holds.
                        // NI.nyi("need to verify constraint stated in where clause");
                    }
                }
            } else {
                bug(w, errorMsg("Where clause ", w));
            }
        }
    }
    return et;
}

public void finishObjectTrait(ObjectDecl x, FTypeObject ftt) {
    List<BaseType> extends_ = NodeUtil.getTypes(NodeUtil.getExtendsClause(x));
    finishObjectTrait(extends_, null, NodeUtil.getWhereClause(x), ftt, containing, x);
}

public void finishObjectTrait(_RewriteObjectExpr x, FTypeObject ftt) {
    List<BaseType> extends_ = NodeUtil.getTypes(NodeUtil.getExtendsClause(x));
    // _RewriteObjectExpr has no excludes clause.
    finishObjectTrait(extends_, null, null, ftt, containing, x);
}

static public void finishObjectTrait(List<BaseType> extends_,
                                     List<? extends Type> excludes,
                                     Option<WhereClause> wheres,
                                     FTypeObject ftt,
                                     Environment interior,
                                     HasAt x) {
    interior = interior.extendAt(x);
    EvalType et;
    if (wheres != null && wheres.isSome()) et = processWhereClauses(wheres.unwrap(), interior);
    else et = new EvalType(interior);
    ftt.setExtendsAndExcludes(et.getFTypeListFromList(extends_), et.getFTypeListFromList(excludes), interior);
    if (x instanceof _RewriteObjectExpr && NodeUtil.getStaticParams((_RewriteObjectExpr) x).isEmpty()) {
        // An object expression without static parameters provides its functional
        // methods as a declared object does (checkFunctionalMethodMeets).
        new OverloadedFunction.FunctionalMethodMeets().check(ftt, x);
    }
}

/**
 * Refuses a trait, object or object expression with static parameters,
 * declared as g, one of whose instances breaks the Meet Rule for
 * Functional Methods whatever its static arguments: checks the type that
 * stands for every instance (symbolicInstance) as a declared type without
 * static parameters is checked (checkFunctionalMethodMeets).  A pair of
 * functional methods whose parameter types mention a static parameter, or
 * that a supertype mentioning one provides, is not read.
 */
public static void checkGenericFunctionalMethodMeets(FTypeGeneric g, HasAt at) {
    FTraitOrObject t = symbolicInstance(g);
    if (t != null) new OverloadedFunction.FunctionalMethodMeets().check(t, at);
}

/**
 * The type that stands for every instance of the generic declaration g:
 * a trait or object of g's members whose static parameters are symbolic
 * types (SingleFcn.createSymbolicInstantiation), its extends clause read
 * with them.  It is bound in no environment, is no instance of g, and
 * gives its functional methods to no overloading.  Null for a declaration
 * with an opr parameter, which walk instantiates by rewriting it, and
 * where walk cannot make the type.
 */
private static FTraitOrObject symbolicInstance(FTypeGeneric g) {
    Generic d = g.getDef();
    TraitTypeHeader h;
    if (d instanceof TraitObjectDecl) h = ((TraitObjectDecl) d).getHeader();
    else if (d instanceof _RewriteObjectExpr) h = ((_RewriteObjectExpr) d).getHeader();
    else return null;
    for (StaticParam sp : h.getStaticParams()) {
        if (NodeUtil.isOpParam(sp)) return null;
    }
    try {
        Environment ge = g.getWithin().extendAt(d);
        SingleFcn.createSymbolicInstantiation(h.getStaticParams(), h.getWhereClause(), ge);
        List<FType> extends_ = new EvalType(ge).getFTypeListFromList(NodeUtil.getTypes(h.getExtendsClause()));
        FTraitOrObject t = d instanceof TraitDecl ?
                           new FTypeTrait(g.getName(), ge, d, h.getDecls(), (AbstractNode) d) :
                           new FTypeObject(g.getName(), ge, d, h.getParams(), h.getDecls(), (AbstractNode) d);
        t.setExtendsAndExcludes(extends_, null);
        return t;
    }
    catch (FortressException ex) {
        return null;
    }
}

