    else et = new EvalType(interior);
    List<BaseType> extends_ = holdingExtends(extendsClause, et, interior, ftt);
    ftt.setExtendsAndExcludes(et.getFTypeListFromList(extends_), et.getFTypeListFromList(excludes), interior);

